package main
import("context";"fmt";"time"; b "github.com/cenkalti/backoff/v4")
func genericCase(id string)(out map[string]any){out=map[string]any{};events:=[]string{};t:=newTimer(&events);p:=&policy{delay:b.Stop,events:&events};attempts:=0;ctx,cancel:=context.WithCancel(context.Background());defer cancel();var chosen b.BackOff=p;if id=="generic-cancel"{chosen=b.WithContext(p,ctx)}
 defer func(){if v:=recover();v!=nil{out["panic"]=fmt.Sprint(v)};out["attempts"]=attempts;out["timer_starts"]=t.starts;out["timer_stops"]=t.stops}()
 op:=func()(int,error){attempts++;if attempts>5{return 0,b.Permanent(operationError)};switch id{case"generic-success":return 42,nil;case"generic-final-error":return 73,operationError;case"generic-permanent":return 91,b.Permanent(operationError);case"generic-cancel":cancel();return 17,operationError};panic("unknown generic case")};data,err:=b.RetryNotifyWithTimerAndData(op,chosen,nil,t);out["data"]=data;out["error"]=errorName(err);return}
func optionCase(id string)(out map[string]any){out=map[string]any{};defer func(){if v:=recover();v!=nil{out["panic_present"]=true;out["panic"]=fmt.Sprint(v)}}();c:=&clock{now:time.Unix(0,0)}
 switch id{case"constructor-options":e:=b.NewExponentialBackOff(b.WithInitialInterval(10*time.Millisecond),b.WithRandomizationFactor(0),b.WithMultiplier(2),b.WithMaxInterval(60*time.Millisecond),b.WithMaxElapsedTime(time.Second),b.WithRetryStopDuration(b.Stop),b.WithClockProvider(c));out["initial_ns"]=int64(e.InitialInterval);out["randomization_factor"]=e.RandomizationFactor;out["multiplier"]=e.Multiplier;out["max_interval_ns"]=int64(e.MaxInterval);out["max_elapsed_ns"]=int64(e.MaxElapsedTime);out["stop_ns"]=int64(e.Stop);out["clock_is_owned"]=e.Clock==c;out["clock_now_calls"]=c.calls
 case"constructor-option-order":e:=b.NewExponentialBackOff(b.WithInitialInterval(5*time.Millisecond),b.WithInitialInterval(9*time.Millisecond),b.WithClockProvider(c));out["initial_ns"]=int64(e.InitialInterval);out["clock_now_calls"]=c.calls
 case"nil-clock-option-panic":b.NewExponentialBackOff(b.WithClockProvider(nil))
 case"positive-stop-option-retry":events:=[]string{};t:=newTimer(&events);e:=b.NewExponentialBackOff(b.WithInitialInterval(10*time.Millisecond),b.WithRandomizationFactor(0),b.WithMaxElapsedTime(time.Second),b.WithRetryStopDuration(5*time.Millisecond),b.WithClockProvider(c));attempts,notifications:=0,0;err:=b.RetryNotifyWithTimer(func()error{attempts++;if attempts==1{c.now=c.now.Add(2*time.Second);return operationError};if attempts>5{return b.Permanent(operationError)};return nil},e,func(error,time.Duration){notifications++},t);out["attempts"]=attempts;out["notify"]=notifications;out["timer_starts"]=t.starts;out["delays_ns"]=t.delays;out["error"]=errorName(err)
 default:panic("unknown option case")};return}
func versionSpecific()[]map[string]any{rows:=[]map[string]any{};for _,id:=range []string{"generic-success","generic-final-error","generic-permanent","generic-cancel","constructor-options","constructor-option-order","positive-stop-option-retry","nil-clock-option-panic"}{var observed map[string]any;if len(id)>8&&id[:8]=="generic-"{observed=genericCase(id)}else{observed=optionCase(id)};rows=append(rows,map[string]any{"id":id,"observed":observed})};return rows}
